1	/**
2	 * Chain resolution: pop, settle, repeat until the board is stable.
3	 *
4	 * Pure: given the same board in, the same result comes out. Nothing here
5	 * touches the DOM, timers or randomness — an animating renderer can replay
6	 * `steps` at whatever speed it likes.
7	 */
8	
9	import { cloneMutable, type Board, type Color } from './board.js';
10	import { applyGravity } from './gravity.js';
11	import { findPoppableGroups, POP_THRESHOLD, type Group } from './groups.js';
12	
13	/** One pop of a chain: everything that popped simultaneously. */
14	export interface ChainStep {
15	  /** 1-based position in the chain. */
16	  readonly chain: number;
17	  /** The groups that popped in this step. */
18	  readonly groups: readonly Group[];
19	  /** Total cells cleared in this step. */
20	  readonly cleared: number;
21	  /** Distinct colours that popped in this step, in first-seen order. */
22	  readonly colors: readonly Color[];
23	  /** The board after this step's pops and the gravity that followed. */
24	  readonly board: Board;
25	}
26	
27	export interface ResolveResult {
28	  /** The stable board: nothing floating, no group of 4+ left. */
29	  readonly board: Board;
30	  /** Number of pop steps. 0 when nothing popped. */
31	  readonly chainCount: number;
32	  /** What popped at each step, in order. */
33	  readonly steps: readonly ChainStep[];
34	  /** Total cells cleared across the whole chain. */
35	  readonly totalCleared: number;
36	}
37	
38	/** Remove every cell listed in `groups`, then let the rest fall. */
39	export function popGroups(board: Board, groups: readonly Group[]): Board {
40	  const next = cloneMutable(board);
41	  for (const group of groups) {
42	    for (const { x, y } of group.cells) next[y]![x] = null;
43	  }
44	  return applyGravity(next);
45	}
46	
47	/**
48	 * Settle the board, then repeatedly pop groups of `threshold`+ and settle
49	 * again, until nothing more pops.
50	 *
51	 * Gravity is applied *before* the first pop check, so a board written as a
52	 * string literal with floating cells behaves like one that was played into
53	 * that shape. That means `result.board` can differ from the input even when
54	 * `chainCount` is 0.
55	 */
56	export function resolve(board: Board, threshold: number = POP_THRESHOLD): ResolveResult {
57	  let current = applyGravity(board);
58	  const steps: ChainStep[] = [];
59	  let totalCleared = 0;
60	
61	  for (;;) {
62	    const groups = findPoppableGroups(current, threshold);
63	    if (groups.length === 0) break;
64	
65	    current = popGroups(current, groups);
66	
67	    const cleared = groups.reduce((sum, g) => sum + g.cells.length, 0);
68	    totalCleared += cleared;
69	    steps.push({
70	      chain: steps.length + 1,
71	      groups,
72	      cleared,
73	      colors: [...new Set(groups.map((g) => g.color))],
74	      board: current,
75	    });
76	  }
77	
78	  return { board: current, chainCount: steps.length, steps, totalCleared };
79	}
