1	/**
2	 * Board model.
3	 *
4	 * Contract (docs/worklog/CONTRACT.md):
5	 *  - 6 wide x 12 tall playfield, plus 1 hidden spawn row on top => 13 rows.
6	 *  - Origin top-left, indexed `board[y][x]`, y grows downward. Never board[x][y].
7	 *  - A cell is a colour or empty; empty is `null` and colours are a non-empty
8	 *    string union, so the two can never be confused.
9	 *
10	 * No DOM, no timers, no randomness in this module (or anywhere under core/).
11	 */
12	
13	/** Playfield width in columns. */
14	export const WIDTH = 6;
15	/** Number of hidden rows above the visible playfield (the spawn row). */
16	export const HIDDEN_ROWS = 1;
17	/** Visible playfield height in rows. */
18	export const VISIBLE_HEIGHT = 12;
19	/** Total row count, hidden row included. Row 0 is hidden. */
20	export const HEIGHT = HIDDEN_ROWS + VISIBLE_HEIGHT;
21	
22	/** The colours a puyo can have. Deliberately none of them is `""`. */
23	export const COLORS = ['red', 'green', 'blue', 'yellow', 'purple'] as const;
24	
25	export type Color = (typeof COLORS)[number];
26	
27	/** A board cell: a colour, or `null` for empty. */
28	export type Cell = Color | null;
29	
30	/** A board is a rectangular grid of rows: `board[y][x]`. */
31	export type Board = readonly (readonly Cell[])[];
32	
33	/** A mutable grid, used internally while building a new board. */
34	export type MutableBoard = Cell[][];
35	
36	/** A position on the board. */
37	export interface Pos {
38	  readonly x: number;
39	  readonly y: number;
40	}
41	
42	const COLOR_SET: ReadonlySet<string> = new Set<string>(COLORS);
43	
44	/** Type guard: is `value` one of the known colours? */
45	export function isColor(value: unknown): value is Color {
46	  return typeof value === 'string' && COLOR_SET.has(value);
47	}
48	
49	/** Number of rows in `board`. */
50	export function boardHeight(board: Board): number {
51	  return board.length;
52	}
53	
54	/** Number of columns in `board`, derived from its first row. */
55	export function boardWidth(board: Board): number {
56	  return board[0]?.length ?? 0;
57	}
58	
59	/**
60	 * An empty board. Defaults to the contract's 6x13, but the size is a parameter
61	 * so tests can use small boards without restating the whole playfield.
62	 */
63	export function createBoard(width: number = WIDTH, height: number = HEIGHT): Board {
64	  if (!Number.isInteger(width) || width < 0) throw new RangeError(`bad width: ${width}`);
65	  if (!Number.isInteger(height) || height < 0) throw new RangeError(`bad height: ${height}`);
66	  return Array.from({ length: height }, () => new Array<Cell>(width).fill(null));
67	}
68	
69	/** Is (x, y) inside `board`? */
70	export function inBounds(board: Board, x: number, y: number): boolean {
71	  return y >= 0 && y < board.length && x >= 0 && x < boardWidth(board);
72	}
73	
74	/**
75	 * The cell at (x, y). Throws on out-of-bounds rather than returning `null`:
76	 * "off the board" and "empty" are different things and conflating them hides
77	 * bugs in flood fill and gravity. Use `inBounds` first when a miss is expected.
78	 */
79	export function getCell(board: Board, x: number, y: number): Cell {
80	  if (!inBounds(board, x, y)) throw new RangeError(`out of bounds: (${x}, ${y})`);
81	  return board[y]![x]!;
82	}
83	
84	/** A copy of `board` with (x, y) set to `cell`. Boards are never mutated. */
85	export function setCell(board: Board, x: number, y: number, cell: Cell): Board {
86	  if (!inBounds(board, x, y)) throw new RangeError(`out of bounds: (${x}, ${y})`);
87	  const next = board.map((row) => row);
88	  next[y] = board[y]!.map((c, i) => (i === x ? cell : c));
89	  return next;
90	}
91	
92	/** A mutable deep copy of `board`, for algorithms that fill a grid in place. */
93	export function cloneMutable(board: Board): MutableBoard {
94	  return board.map((row) => [...row]);
95	}
96	
97	/** Structural equality of two boards. */
98	export function boardsEqual(a: Board, b: Board): boolean {
99	  if (a.length !== b.length) return false;
100	  return a.every((row, y) => {
101	    const other = b[y]!;
102	    return row.length === other.length && row.every((cell, x) => cell === other[x]);
103	  });
104	}
105	
106	/** Every position on the board, in row-major (top-to-bottom) order. */
107	export function* positions(board: Board): Generator<Pos> {
108	  const width = boardWidth(board);
109	  for (let y = 0; y < board.length; y++) {
110	    for (let x = 0; x < width; x++) yield { x, y };
111	  }
112	}
